We start by proving the following 2 auxiliary statements:

\begin{cor}
\label{cor:internal-subspaces-gen}Let $S'\subseteq S$ be linear
subspaces in a vector space over $\mathbb{F}_{q}$. Let $d$ and $t$
be nonnegative integers. Then the number of dimension-$d$ linear
subspaces $T\subseteq S$ with $\dim(S'\cap T)=t$ is
\begin{equation}
q^{(\dim(S')-t)(d-t)}\binom{\dim(S)-\dim(S')}{d-t}_{q}\binom{\dim(S')}{t}_{q}.\label{eq:counting-internally-gen}
\end{equation}
\end{cor}
\begin{proof}
Invoke \prettyref{lem:external-subspaces-gen} with $V=S,$ $A=S',$
and $B=\{0\}.$
\end{proof}

\begin{prop}
\label{prop:J-normalization}Let $n,m,\ell,r$ be nonnegative integers
with $\max\{m,\ell\}\leq n$. Then 
\begin{align}
J_{r}^{n,m,\ell}\,\1 & =q^{(m-r)(\ell-r)}\binom{n-m}{\ell-r}_{q}\binom{m}{r}_{q}\1\label{eq:1-eigenvector}\\
 & =\Lambda_{r}^{n,m,\ell}(0)\,\1,\label{eq:eq:1-eigenvector-Lambda0}\\
\|J_{r}^{n,m,\ell}\|_{1} & =q^{(m-r)(\ell-r)}\binom{n-m}{\ell-r}_{q}\binom{m}{r}_{q}\binom{n}{m}_{q}.\label{eq:Jnml-r-ell1-norm}
\end{align}
More generally, for $\phi\colon\mathbb{Z}\to\Re,$
\begin{align}
J_{\phi}^{n,m,\ell}\,\1 & =\Lambda_{\phi}^{n,m,\ell}(0)\,\1,\label{eq:1-eigenvector-phi}\\
\|J_{\phi}^{n,m,\ell}\|_{1} & =\sum_{r=0}^{\min\{m,\ell\}}|\phi(r)|\,q^{(m-r)(\ell-r)}\binom{n-m}{\ell-r}_{q}\binom{m}{r}_{q}\binom{n}{m}_{q}.\label{eq:Jnml-phi-ell1-norm}
\end{align}
\end{prop}
\begin{proof}
Let $A\subseteq\mathbb{F}_{q}^{n}$ be a subspace of dimension $m.$
By definition, $(J_{r}^{n,m,\ell}\,\1)_{A}$ is the number of $\ell$-dimensional
subspaces $X\subseteq\mathbb{F}_{q}^{n}$ with $\dim(A\cap X)=r.$
Taking $S'=A$ and $S=\mathbb{F}_{q}^{n}$ in Corollary~\ref{cor:internal-subspaces-gen},
we obtain
\[
(J_{r}^{n,m,\ell}\,\1)_{A}=q^{(m-r)(\ell-r)}\binom{n-m}{\ell-r}_{q}\binom{m}{r}_{q}.
\]
This settles~\eqref{eq:1-eigenvector}, which in turn implies~\eqref{eq:eq:1-eigenvector-Lambda0}
by Definition~\ref{def:Lambda}. Since there are exactly $\binom{n}{m}_{q}$
subspaces $A\subseteq\mathbb{F}_{q}^{n}$ of dimension $m,$ equation~\eqref{eq:Jnml-r-ell1-norm}
is immediate from~\eqref{eq:1-eigenvector}. Equation~\eqref{eq:1-eigenvector-phi}
follows by linearity from~\eqref{eq:J-phi-def} and~\eqref{eq:eq:1-eigenvector-Lambda0}.
Analogously, \eqref{eq:Jnml-phi-ell1-norm} follows from~\eqref{eq:J-phi-def}
and~\eqref{eq:Jnml-r-ell1-norm} since the matrices $J_{r}^{n,m,\ell}$
for $r\geq0$ have disjoint support.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
Let $r\in\{0,1,\ldots,\min\{m,\ell\}\}$ be given. Then
\begin{align}
\overline{\Lambda}_{r}^{\,n,m,\ell}(k) & =\frac{1}{\|J_{r}^{n,m,\ell}\|_{1}}\Lambda_{r}^{n,m,\ell}(k)\nonumber \\
 & =\frac{1}{\|J_{r}^{n,m,\ell}\|_{1}}\sum_{i=0}^{k}(-1)^{i}\binom{k}{i}_{q}q^{\binom{i}{2}+(m-r)(\ell-r-i)}\binom{n-m-i}{\ell-r-i}_{q}\binom{m-k+i}{r-k+i}_{q}\nonumber \\
 & =\binom{n}{m}_{q}^{-1}\sum_{i=0}^{k}(-1)^{i}\binom{k}{i}_{q}\frac{q^{\binom{i}{2}+(m-r)(\ell-r-i)}}{q^{(m-r)(\ell-r)}}\cdot\frac{\binom{n-m-i}{\ell-r-i}_{q}}{\binom{n-m}{\ell-r}_{q}}\cdot\frac{\binom{m-k+i}{r-k+i}_{q}}{\binom{m}{r}_{q}},\label{eq:Lambda-bar-begin}
\end{align}
where the first step restates Definition~\prettyref{def:Lambda-bar},
the second step applies Definition~\prettyref{def:Lambda}, and the
final step uses~\prettyref{prop:J-normalization}. To simplify~\prettyref{eq:Lambda-bar-begin},
observe that
\begin{equation}
\frac{\binom{n-m-i}{\ell-r-i}_{q}}{\binom{n-m}{\ell-r}_{q}}=\frac{q^{\ell-r}-1}{q^{n-m}-1}\cdot\frac{q^{\ell-r}-q}{q^{n-m}-q}\cdot\cdots\cdot\frac{q^{\ell-r}-q^{i-1}}{q^{n-m}-q^{i-1}}.\label{eq:gaussian-ratio1}
\end{equation}
Indeed, if $\ell-r-i<0,$ then the left-hand side is zero by definition,
and the right-hand side also evaluates to zero. In the complementary
case $\ell-r-i\geq0,$ one obtains~\prettyref{eq:gaussian-ratio1}
directly from the definition of Gaussian binomial coefficients. One
analogously verifies that
\begin{equation}
\frac{\binom{m-k+i}{r-k+i}_{q}}{\binom{m}{r}_{q}}=\frac{q^{r}-1}{q^{m}-1}\cdot\frac{q^{r}-q}{q^{m}-q}\cdot\cdots\cdot\frac{q^{r}-q^{k-i-1}}{q^{m}-q^{k-i-1}},\label{eq:gaussian-ratio2}
\end{equation}
by considering the cases $r-k+i<0$ and $r-k+i\geq0.$ Substituting~\prettyref{eq:gaussian-ratio1}
and~\prettyref{eq:gaussian-ratio2} into~\prettyref{eq:Lambda-bar-begin}
gives
\begin{align}
\overline{\Lambda}_{r}^{\,n,m,\ell}(k) & =\binom{n}{m}_{q}^{-1}\sum_{i=0}^{k}(-1)^{i}\binom{k}{i}_{q}q^{\binom{i}{2}-(m-r)i}\cdot\frac{q^{\ell-r}-1}{q^{n-m}-1}\cdot\frac{q^{\ell-r}-q}{q^{n-m}-q}\cdot\cdots\cdot\frac{q^{\ell-r}-q^{i-1}}{q^{n-m}-q^{i-1}}\nonumber \\
 & \qquad\qquad\qquad\qquad\qquad\qquad\qquad\times\frac{q^{r}-1}{q^{m}-1}\cdot\frac{q^{r}-q}{q^{m}-q}\cdot\cdots\cdot\frac{q^{r}-q^{k-i-1}}{q^{m}-q^{k-i-1}}.\label{eq:Lambda-bar-simplified}
\end{align}

To verify the algebraic property~\prettyref{enu:Lambda-bar-poly},
rewrite~\prettyref{eq:Lambda-bar-simplified} to obtain
\begin{multline*}
\overline{\Lambda}_{r}^{\,n,m,\ell}(k)=\binom{n}{m}_{q}^{-1}\sum_{i=0}^{k}(-1)^{i}\binom{k}{i}_{q}q^{\binom{i}{2}-mi}\cdot\frac{q^{\ell}-q^{r}}{q^{n-m}-1}\cdot\frac{q^{\ell}-q^{r+1}}{q^{n-m}-q}\cdot\cdots\cdot\frac{q^{\ell}-q^{r+i-1}}{q^{n-m}-q^{i-1}}\\
\times\frac{q^{r}-1}{q^{m}-1}\cdot\frac{q^{r}-q}{q^{m}-q}\cdot\cdots\cdot\frac{q^{r}-q^{k-i-1}}{q^{m}-q^{k-i-1}}.\qquad
\end{multline*}
The $i$-th summand in this expression is, for fixed values of $n,m,\ell,k,$
clearly a polynomial in $q^{r}$ of degree at most $i+(k-i)=k.$ This
settles~\prettyref{enu:Lambda-bar-poly}.

We now turn to the analytic property,~\prettyref{enu:Lambda-bar-bound}.
Dropping the zero terms from the summation in~\prettyref{eq:Lambda-bar-simplified},
and applying the triangle inequality,
\begin{align*}
|\overline{\Lambda}_{r}^{\,n,m,\ell}(k)| & \leq\binom{n}{m}_{q}^{-1}\sum_{i=\max\{0,k-r\}}^{\min\{k,\ell-r\}}\binom{k}{i}_{q}q^{\binom{i}{2}-(m-r)i}\cdot\frac{q^{\ell-r}-1}{q^{n-m}-1}\cdot\frac{q^{\ell-r}-q}{q^{n-m}-q}\cdot\cdots\cdot\frac{q^{\ell-r}-q^{i-1}}{q^{n-m}-q^{i-1}}\\
 & \qquad\qquad\qquad\qquad\qquad\qquad\qquad\times\frac{q^{r}-1}{q^{m}-1}\cdot\frac{q^{r}-q}{q^{m}-q}\cdot\cdots\cdot\frac{q^{r}-q^{k-i-1}}{q^{m}-q^{k-i-1}}.
\end{align*}
The first $i$ fractions on the right-hand side are each bounded by
$q^{\ell-r}/q^{n-m},$ whereas the other $k-i$ fractions are each
bounded by $q^{r}/q^{m}$. Using these estimates leads to
\begin{align}
|\overline{\Lambda}_{r}^{\,n,m,\ell}(k)| & \leq\binom{n}{m}_{q}^{-1}\sum_{i=\max\{0,k-r\}}^{\min\{k,\ell-r\}}\binom{k}{i}_{q}q^{\binom{i}{2}-(m-r)i}\cdot q^{(\ell-r-n+m)i}\cdot q^{-(m-r)(k-i)}\nonumber \\
 & \leq\binom{n}{m}_{q}^{-1}\sum_{i=\max\{0,k-r\}}^{\min\{k,\ell-r\}}4q^{i(k-i)+\binom{i}{2}-(m-r)i+(\ell-r-n+m)i-(m-r)(k-i)}\nonumber \\
 & \leq\binom{n}{m}_{q}^{-1}\sum_{i=\max\{0,k-r\}}^{\min\{k,\ell-r\}}4q^{i(k-i)+\binom{i}{2}-(m-r)i-ri-(m-r)(k-i)}\nonumber \\
 & =\binom{n}{m}_{q}^{-1}\sum_{i=\max\{0,k-r\}}^{\min\{k,\ell-r\}}4q^{i(k-r-i)+\binom{i}{2}-k(m-r)},\label{eq:Lambda-bound-closer}
\end{align}
where the second step uses~\prettyref{cor:qbinbound}, and the third
step is valid since $n\geq m+\ell$ by hypothesis. Let $A(i)$ denote
the exponent of $q$ in~\prettyref{eq:Lambda-bound-closer}. Then
$A(i)$ is an integer-valued function of $i$ that strictly decreases
on $[k-r,\infty)$. As a result, \prettyref{eq:Lambda-bound-closer}
yields
\begin{align*}
|\overline{\Lambda}_{r}^{\,n,m,\ell}(k)| & \leq\binom{n}{m}_{q}^{-1}\sum_{t=0}^{\infty}4q^{A(\max\{0,k-r\})-t}\\
 & \leq8\binom{n}{m}_{q}^{-1}q^{A(\max\{0,k-r\})},
\end{align*}
where the second step uses a geometric series along with $q\geq2.$
Therefore, the proof of~\prettyref{enu:Lambda-bar-bound} will be
complete once we show that
\begin{equation}
A(\max\{0,k-r\})\leq-\frac{k(m-r)}{2}.\label{eq:A-max}
\end{equation}
There are two cases to consider. If $k\leq r,$ then $A(\max\{0,k-r\})=A(0)=-k(m-r)\leq-k(m-r)/2,$
where the last step uses the hypothesis that $r\leq m.$ If $k>r,$
then $A(\max\{0,k-r\})=A(k-r)=\binom{k-r}{2}-k(m-r)\leq k(k-r)/2-k(m-r)\leq-k(m-r)/2$,
where the last step uses the hypothesis that $k\leq m.$ This settles~\prettyref{eq:A-max}
and completes the proof of the lemma.
\end{proof}
